const is = (x, ...names) => names.includes(part(x).name)
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz, exact equal temperament
const SW = 0.5 // the off-beat eighth lands at 0.5 of the beat
const ROLE = [[0,"intro",1],[32,"build",2],[48,"theme",3],[112,"themeB",2],[144,"bridge",1],[176,"build",2],[192,"final",3],[256,"outro",1]] // [start, role, energy 0–3] per section
const sectionOf = x => { let s = ROLE[0]; for (const r of ROLE) if (r[0] <= x) s = r; return s }
const energy = x => (x < END ? sectionOf(x)[2] : -1)
const role = x => (x < END ? sectionOf(x)[1] : 'end')

